    /**
     * 「已安装 / 启动项」对不上时的说明。
     * 用户的直觉是「我装了 21 个，怎么就 20 个在跑」，所以这里把它讲明白。
     */
    function joinShort(list) {
      var arr = Array.isArray(list) ? list : [];
      if (!arr.length) return "";
      var head = arr.slice(0, 3).join("、");
      return arr.length > 3 ? head + " 等 " + arr.length + " 个" : head;
    }

    function pendingText(current) {
      var installed = current.pluginCount;
      var started = current.bundleCount;
      if (installed === null || installed === undefined || started === null || started === undefined) {
        return "暂时读不到插件清单。";
      }
      var pending = Array.isArray(current.pendingPlugins) ? current.pendingPlugins : [];
      var orphan = Array.isArray(current.orphanBundles) ? current.orphanBundles : [];

      if (pending.length) {
        return (
          "已安装 " + installed + " 个插件，真正加进启动项的只有 " + started + " 个：" +
          joinShort(pending) + " 装了但还没生效 —— 完全退出 DSH 再打开才会运行。"
        );
      }
      if (orphan.length) {
        return (
          "启动项里有 " + joinShort(orphan) + "，但对应的插件没有装上，重启时会报错或跳过；" +
          "建议先修好它，或恢复一份健康快照。"
        );
      }
      if (installed === started) {
        return "已安装 " + installed + " 个插件，启动项 " + started + " 个：全部生效，状态一致。";
      }
      return "已安装 " + installed + " 个插件，启动项 " + started + " 个：两边对不上，建议恢复一份健康快照后重启。";
    }

